Hi Rstan's

With the suggestion of Bob, I don't already arrived to run my model.
I write hierarchical multimodel where in first level, I write Rasch model for responses and
lognormal for responses times.
In second the parameters of persons are bivariate normale. Also parameters of Items.

With bivariate priors in manuel of rstan, I write the script below :

data {

   int P; // # Individus

   int Q; // # Items

   real logTwNA[P,Q]; // Log responses times

   real IndwNA[P,Q]; // NA index  (1 if NA, 0 ifelse)

   int RwNA[P,Q]; // Responses

}

parameters {

matrix[2,P] zP;

   vector[2] muP;

   cholesky_factor_corr[2] L_rhoP;

   vector<lower=0>[2] sigmaP;

   matrix[2,Q] zQ;

   vector[2] muQ;

   cholesky_factor_corr[2] L_rhoQ;

   vector<lower=0>[2] sigmaQ;

   vector<lower=0>[Q] sigmaT;

}

transformed parameters{

        // to define second level -  constraints of parameters (In looking in manuel)

matrix[2,P] paramP; // Parameters of persons (theta,tau)

matrix[2,Q] paramQ; // Parameters of items (betaR,betaT)

paramP <- to_matrix(muP) + (diag_pre_multiply(sigmaP,L_rhoP) * zP);

paramQ <- to_matrix(muQ) + (diag_pre_multiply(sigmaQ,L_rhoQ) * zQ) ;

}

model {

   // Priors

   sigmaT ~ cauchy(0,2.5);

   muP ~ normal(0,1);

   sigmaP ~ cauchy(0,2.5);

   L_rhoP ~ lkj_corr_cholesky(2);

   to_vector(zP) ~ normal(0,1);

   muQ ~ normal(0,1);

   sigmaQ ~ cauchy(0,2.5);

   L_rhoQ ~ lkj_corr_cholesky(2);

        to_vector(zQ) ~ normal(0,1);

   for(p in 1:P)

   {

     for(q in 1:Q)

     {

       if(IndwNA[p,q]==0)

       {

         RwNA[p,q] ~ bernoulli_logit(paramP[1,p]-paramQ[1,q]);

         logTwNA[p,q] ~ normal(paramQ[2,q] - paramP[2,p],sigmaT[q]);

      }

      }

}

   // 2nd level

   //paramP ~ multi_normal(muP,(diag_pre_multiply(sigmaP,L_rhoP)*zP));

//paramQ ~ multi_normal(muQ,(diag_pre_multiply(sigmaQ,L_rhoQ)*zQ));

}

