    data{
      int P;                        //nr items
      int N;                       //nr persons
      int K[P];                   //nr categories per item -1
      int Y[N, P];                  // data
    }

    parameters {
      ordered[max(K)] kappa[P];              // intercepts
      real theta[N];                                    //person parameter
