Hello,

This is my first attempt to fit a multivariate normal distribution with (r)stan using a LKJ prior. My code is given below. I set a zero mean so that the covariance matrix is the only unknown parameter.

I get some numerical problems :

> validate transformed params: Sigma is not positive definite
> validate transformed params: Sigma is not symmetric. Sigma[1,2] = -nan, but Sigma[2,1] = -nan
> Exception thrown at line 23: lkj_corr_log: y is not positive definite
> validate transformed params: Sigma is not symmetric. Sigma[1,2] = inf, but Sigma[2,1] = inf

Is it important ? Is there a way to avoid these problems ?
This apart, the results look quite good.

library(rstan)
rstan_options(auto_write = TRUE)
options(mc.cores = parallel::detectCores())

stancode <- 'data {
  int<lower=1> N; // number of observations
  int<lower=1> J; // dimension of observations
  vector[J] y[N]; // observations
  vector[J] zero; // a vector of zeros (means of observations)
  int<lower=1> nu; // shape of the LKJ prior
}
parameters {
  corr_matrix[J] Omega;
  vector<lower=0>[J] sigma;
}
transformed parameters {
  cov_matrix[J] Sigma; // varcov matrix
  for(i in 1:J){
    for(j in 1:J){
      Sigma[i,j] <- sigma[i] * sigma[j] * Omega[i,j];
    }
  }
}
model {
  y ~ multi_normal(zero,Sigma);
  sigma ~ gamma(0.1, 0.1);
  Omega ~ lkj_corr(nu);
}'

# compile model
stanmodel <- stan_model(model_code = stancode, model_name="stanmodel_multinormal")

# data
Omega <- rbind(
  c(1, 0.3, 0.2),
  c(0.3, 1, 0.1),
  c(0.2, 0.1, 1)
)
sigma <- c(1, 2, 3)
Sigma <- diag(sigma) %*% Omega %*% diag(sigma)
N <- 100
y <- mvtnorm::rmvnorm(N, c(0,0,0), Sigma)

# stan data
standata <- list(J = 3, N=N, y = y, zero=rep(0,3), nu=1)

# stan inits
inits <- function(chain_id){
  L <- list(Omega=Omega, sigma=sigma*rgamma(3,10,10))
  return(L)
}

# run stan
samples <- sampling(stanmodel, data = standata, init=inits,
                    iter = 10000, warmup = 1000, chains = 4)

